// ─── Helper functions ─────────────────────────
window.VOCAB_HELPERS = {
  byLevel: (level) => window.DB_VOCAB.filter(v => v.level === level),
  byTopic: (topic) => window.DB_VOCAB.filter(v => v.topic === topic),
  byLevelAndTopic: (level, topic) => window.DB_VOCAB.filter(v => v.level === level && v.topic === topic),
  random: (level, n = 10) => {
    const pool = level ? window.DB_VOCAB.filter(v => v.level === level) : window.DB_VOCAB;
    const shuffled = [...pool].sort(() => Math.random() - 0.5);
    return shuffled.slice(0, n);
  },
  highFrequency: (level) => window.DB_VOCAB.filter(v => v.level === level && v.freq === 1),
  topics: (level) => [...new Set(window.DB_VOCAB.filter(v => v.level === level).map(v => v.topic))],
  totalByLevel: (level) => window.DB_VOCAB.filter(v => v.level === level).length,
};

