window.DB_CULTURAL = [
  {id:"c001",level:"A1",title:"Duzen vs. Siezen",body:"In German, 'du' is informal (friends, family, children) and 'Sie' is formal (strangers, bosses, shops). Getting this wrong is the most common foreigner mistake!",emoji:"🤝"},
  {id:"c002",level:"A1",title:"German greetings differ by region",body:"'Hallo' is universal, but in Bavaria you'll hear 'Servus', in Austria 'Grüß Gott', and in Switzerland 'Grüezi'. They all mean hello!",emoji:"🗺️"},
  {id:"c003",level:"A1",title:"Der, die, das — why three?",body:"German has three grammatical genders — not related to biological sex. 'das Mädchen' (the girl) is grammatically neuter, not feminine. Genders must be memorised!",emoji:"📚"},
  {id:"c004",level:"A2",title:"Punctuality in Germany",body:"Germans consider punctuality a sign of respect. Being 15 minutes late to a dinner invitation is normal in some cultures, but in Germany it is considered rude. 'Pünktlichkeit ist eine Tugend.'",emoji:"⏰"},
  {id:"c005",level:"A2",title:"The German recycling system",body:"Germany has one of the world's most advanced recycling systems. 'Mülltrennung' (waste separation) is mandatory — different bins for paper, plastic, glass, and bio waste. There's even a bottle deposit ('Pfand') system!",emoji:"♻️"},
  {id:"c006",level:"A2",title:"Bread culture — 'Brotkultur'",body:"Germany has over 3,000 types of registered bread. German bread culture is so significant it's recognised by UNESCO. The word 'Abendbrot' (evening bread) shows that bread is even eaten at dinner.",emoji:"🍞"},
  {id:"c007",level:"B1",title:"Compound words — Komposita",body:"German loves combining words to create new ones. 'Donaudampfschiffahrtsgesellschaftskapitän' = Danube steamship company captain. The longest legally valid German word had 63 characters before the law changed!",emoji:"🔤"},
  {id:"c008",level:"B1",title:"The Autobahn — no speed limit?",body:"About 30% of the Autobahn has no speed limit ('freie Fahrt'). However, the recommended speed is 130 km/h. Tailgating at any speed is illegal and one of the most common traffic offences.",emoji:"🚗"},
  {id:"c009",level:"B1",title:"Mittagspause — the lunch break culture",body:"Many German shops close between 12–14:00 for lunch. In smaller towns, some businesses still close on Wednesday afternoon ('Mittwochnachmittag'). This reflects the importance Germans place on structured work-life balance.",emoji:"🍽️"},
  {id:"c010",level:"B1",title:"Direct communication style",body:"Germans are often perceived as blunt or direct. Saying 'Das schmeckt nicht' (that doesn't taste good) is honest, not rude. Indirect criticism is seen as dishonest. This is cultural, not personal.",emoji:"💬"},
  {id:"c011",level:"B2",title:"Vergangenheitsbewältigung",body:"Germany takes its responsibility for the Nazi period extremely seriously. Holocaust denial is illegal. The country has memorials, mandatory school curricula, and continues to pay reparations. 'Nie wieder' (Never again) is a national principle.",emoji:"🕊️"},
  {id:"c012",level:"B2",title:"The German education system",body:"At age 10, German children are sorted into different school tracks: Gymnasium (academic), Realschule (mixed), or Hauptschule (vocational). This early sorting is controversial and differs by state ('Bundesland').",emoji:"🎓"},
  {id:"c013",level:"B2",title:"Sozialmarktwirtschaft",body:"Germany's economic model is the 'social market economy' — a blend of free markets with strong social protections. It emphasises worker rights (Mitbestimmung), universal healthcare, and the welfare state ('Sozialstaat').",emoji:"⚖️"},
  {id:"c014",level:"C1",title:"The concept of 'Gemütlichkeit'",body:"'Gemütlichkeit' has no direct English translation. It describes a sense of warmth, cosiness, and belonging in a social space — the feeling of a cosy Christmas market, a warm pub, or a comfortable family gathering. More than just 'cosy'.",emoji:"🕯️"},
  {id:"c015",level:"C1",title:"Föderalismus in Germany",body:"Germany is a federal republic of 16 states ('Bundesländer'). Each state has its own parliament, school system, and cultural identity. Bavaria (Bayern) is particularly proud of its distinct culture and sometimes refers to itself as the 'Freistaat'.",emoji:"🗳️"},
  {id:"c016",level:"C1",title:"Goethe, Schiller, and the canon",body:"Goethe and Schiller are to German culture what Shakespeare is to English — central to national identity. 'Faust', 'Die Leiden des jungen Werthers', and 'Die Räuber' are canonical works every educated German is expected to know.",emoji:"📖"}
];

